 using Microsoft.Extensions.DependencyInjection;
 using Microsoft.Extensions.Logging;
 using OpenAI;

 // ── Configuration ──────────────────────────────────────────────────────────
 var apiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY")
     ?? throw new InvalidOperationException(
         "Set the OPENAI_API_KEY environment variable before running.");

 var modelId = Environment.GetEnvironmentVariable("OPENAI_MODEL") ?? "gpt-4o-mini-2024-07-18";

 // ── DI & Services ──────────────────────────────────────────────────────────
 var services = new ServiceCollection();
 services.AddLogging(b => b.AddConsole().SetMinimumLevel(LogLevel.Warning));
 services.AddSingleton<IChatClient>(new OpenAIClient(apiKey).GetChatClient(modelId).AsIChatClient());

 var sp = services.BuildServiceProvider();

 var chatClient = sp.GetRequiredService<IChatClient>();
 var loggerFactory = sp.GetRequiredService<ILoggerFactory>();

 // ── Tools ──────────────────────────────────────────────────────────────────
 var notepad = new Notepad();

 var tools = new AITool[]
 {
     AIFunctionFactory.Create(WebSearchTool.SearchAsync),
     AIFunctionFactory.Create(notepad.SaveNote),
     AIFunctionFactory.Create(notepad.GetNotes),
 };

 // ── Agent ──────────────────────────────────────────────────────────────────
 var agent = new ChatClientAgent(
     chatClient,
     instructions: """
         You are a research agent. When the user gives you a topic:
         1. Search the web for relevant information (make 2-3 searches with varied queries).
         2. Save the key findings as notes using the note-taking tool.
         3. After gathering enough information, retrieve all notes and produce a
            well-structured summary with sections and source URLs.
         Always cite your sources.
         """,
     name: "ResearchAgent",
     description: "An agent that researches topics by searching the web and summarizing findings.",
     tools: tools,
     loggerFactory: loggerFactory,
     services: sp);

 // ── Run ────────────────────────────────────────────────────────────────────
 var topic = args.Length > 0
     ? string.Join(' ', args)
     : PromptUser("Enter a research topic: ");

