 // ── Web Search Tool ────────────────────────────────────────────────────────
 static class WebSearchTool
 {
     private static readonly HttpClient Http = new()
     {
         DefaultRequestHeaders =
         {
             { "User-Agent", "ResearchAgent/1.0" },
             { "Accept", "text/html" },
         },
         Timeout = TimeSpan.FromSeconds(15),
     };

     [Description("Search the web for information on a query. Returns a list of result titles, snippets, and URLs.")]
     public static async Task<string> SearchAsync(
         [Description("The search query to look up")] string query,
         CancellationToken cancellationToken = default)
     {
         try
         {
             var encoded = WebUtility.UrlEncode(query);
             var url = $"https://html.duckduckgo.com/html/?q={encoded}";
             var html = await Http.GetStringAsync(url, cancellationToken);
             return ParseResults(html, maxResults: 5);
         }
         catch (Exception ex)
         {
             return $"Search failed: {ex.Message}";
         }
     }

     private static string ParseResults(string html, int maxResults)
     {
         var results = new List<string>();
         var index = 0;

         while (results.Count < maxResults)
         {
             // Find result links (class="result__a")
             var linkStart = html.IndexOf("class=\"result__a\"", index, StringComparison.Ordinal);
             if (linkStart < 0) break;

             var href = ExtractAttribute(html, linkStart, "href");
             var title = ExtractInnerText(html, linkStart);

             // Find snippet (class="result__snippet")
             var snippetStart = html.IndexOf("class=\"result__snippet\"", linkStart, StringComparison.Ordinal);
             var snippet = snippetStart >= 0 ? ExtractInnerText(html, snippetStart) : "";

             if (!string.IsNullOrWhiteSpace(title))
             {
                 results.Add($"Title: {WebUtility.HtmlDecode(title.Trim())}\n" +
                             $"URL: {WebUtility.HtmlDecode(href?.Trim() ?? "N/A")}\n" +
                             $"Snippet: {WebUtility.HtmlDecode(snippet.Trim())}");
             }

             index = snippetStart >= 0 ? snippetStart + 1 : linkStart + 1;
         }

         return results.Count > 0
             ? string.Join("\n---\n", results)
             : "No results found.";
     }

     private static string? ExtractAttribute(string html, int startFrom, string attr)
     {
         var attrPattern = $"{attr}=\"";
         var attrStart = html.LastIndexOf(attrPattern, startFrom, Math.Min(startFrom, 500), StringComparison.Ordinal);
         if (attrStart < 0)
         {
             attrStart = html.IndexOf(attrPattern, startFrom, StringComparison.Ordinal);
         }

         if (attrStart < 0) return null;
         var valueStart = attrStart + attrPattern.Length;
         var valueEnd = html.IndexOf('"', valueStart);
         return valueEnd > valueStart ? html[valueStart..valueEnd] : null;
     }

     private static string ExtractInnerText(string html, int startFrom)
     {
         var tagEnd = html.IndexOf('>', startFrom);
         if (tagEnd < 0) return "";
         var contentStart = tagEnd + 1;
         var contentEnd = html.IndexOf('<', contentStart);
         return contentEnd > contentStart ? html[contentStart..contentEnd] : "";
     }
 }

 // ── Notepad Tool ───────────────────────────────────────────────────────────
 sealed class Notepad
 {
     private readonly List<string> _notes = [];

     [Description("Save a research note. Use this to record key findings from search results.")]
     public string SaveNote(
         [Description("The note content to save, including source URL if available")] string note)
     {
         _notes.Add(note);
         return $"Note #{_notes.Count} saved.";
     }

     [Description("Retrieve all saved research notes so far.")]
     public string GetNotes()
     {
         if (_notes.Count == 0)
             return "No notes saved yet.";

         return string.Join("\n\n", _notes.Select((n, i) => $"[Note {i + 1}]\n{n}"));
     }
 }

